// Version files generated by the CI at the app root, by priority.
const (
	DeployInfoJSON = ".app.lacis.json"
	DeployInfoYAML = ".app.lacis.yaml"
	DeployInfoYML  = ".app.lacis.yml"
)

var deployInfoFiles = []string{DeployInfoJSON, DeployInfoYAML, DeployInfoYML}

// deployInfo is the content of a version file; every field is optional but
// version and commit. The version is the tag deployed or, for an env that
// deploys a branch, the branch.
type deployInfo struct {
	Project     string     `json:"project" yaml:"project"`
	App         string     `json:"app" yaml:"app"`
	Env         string     `json:"env" yaml:"env"`
	Version     string     `json:"version" yaml:"version"`
	Commit      string     `json:"commit" yaml:"commit"`
	Branch      string     `json:"branch" yaml:"branch"`
	Tag         string     `json:"tag" yaml:"tag"`
	Repository  string     `json:"repository" yaml:"repository"`
	PipelineID  string     `json:"pipeline_id" yaml:"pipeline_id"`
	PipelineURL string     `json:"pipeline_url" yaml:"pipeline_url"`
	DeployedAt  *time.Time `json:"deployed_at" yaml:"deployed_at"`
	DeployedBy  string     `json:"deployed_by" yaml:"deployed_by"`
}

// readDeployInfo reads the version file of an app, nil when there is none.
// With several files, the first of deployInfoFiles wins and a warning is
// returned.
func readDeployInfo(fsys afero.Fs, root string) (*deployInfo, []error) {
	var found []string
	for _, name := range deployInfoFiles {
		if _, err := fsys.Stat(path.Join(root, name)); err == nil {
			found = append(found, name)
		}
	}
	if len(found) == 0 {
		return nil, nil
	}
	var warnings []error
	if len(found) > 1 {
		warnings = append(warnings, fmt.Errorf("%s: several version files (%s), %s used", root, strings.Join(found, ", "), found[0]))
	}
	file := path.Join(root, found[0])
	b, err := fsutil.ReadAppFile(fsys, file)
	if err != nil {
		return nil, append(warnings, err)
	}
	info := &deployInfo{}
	if found[0] == DeployInfoJSON {
		err = json.Unmarshal(b, info)
	} else {
		err = yaml.Unmarshal(b, info)
	}
	if err != nil {
		return nil, append(warnings, fmt.Errorf("%s: %w", file, err))
	}
	if info.Version == "" || info.Commit == "" {
		warnings = append(warnings, fmt.Errorf("%s: version file without version or commit", root))
	}
	// project and env become slugs on the server: a value that is not one
	// is dropped, the app keeping those of its host.
	for _, f := range []struct {
		key   string
		value *string
	}{{labels.KeyProject, &info.Project}, {labels.KeyEnv, &info.Env}} {
		if *f.value != "" && !labels.IsSlug(*f.value) {
			warnings = append(warnings, fmt.Errorf("%s: %s %q is not a slug, ignored", file, f.key, *f.value))
			*f.value = ""
		}
	}
	info.Repository = stripCredentials(info.Repository)
	return info, warnings
}

func (i *deployInfo) code() *snapshot.Code {
	return &snapshot.Code{
		Source:      snapshot.CodeSourceDeployInfo,
		Version:     i.Version,
		Commit:      i.Commit,
		Branch:      i.Branch,
		Tag:         i.Tag,
		Repository:  i.Repository,
		PipelineID:  i.PipelineID,
		PipelineURL: i.PipelineURL,
		DeployedAt:  i.DeployedAt,
		DeployedBy:  i.DeployedBy,
	}
}

// code is the code of an app read from its .git directory. The version is
// the tag of the commit or, without tag, the branch: an env such as staging
// deploys its branch rather than a tag.
func (r *gitRepo) code() *snapshot.Code {
	version := r.tag
	if version == "" {
		version = r.branch
	}
	return &snapshot.Code{Source: snapshot.CodeSourceGit, Version: version, Commit: r.commit, Branch: r.branch, Tag: r.tag, Repository: r.remote}
}

// gitRepo is what is read of a .git directory, without the git binary.
type gitRepo struct {
	commit string
	branch string
	tag    string
	remote string
}

// Limits of the files read in a .git directory: HEAD and a loose ref hold
// one line.
const (
	maxRefFile    = 256
	maxGitConfig  = 64 << 10
	maxPackedRefs = 4 << 20
)

var (
	// shaRe is a SHA-1 or SHA-256 commit id.
	shaRe = regexp.MustCompile(`^[0-9a-f]{40}([0-9a-f]{24})?$`)
	// refRe is a ref name; ".." is refused apart.
	refRe = regexp.MustCompile(`^refs/[A-Za-z0-9._/-]+$`)

	errInvalidRef = errors.New("invalid ref in HEAD")
)

// readGit reads HEAD, the refs and the origin remote of the repository of
// root; nil without .git. A .git file ("gitdir: …") points to the real
// directory, as for worktrees and submodules; it is only followed under
// root.
//
// The agent runs as root and the repository belongs to the app: every file
// is read through a file system confined to root, which refuses ".." and the
// links leading out of it, and only the values of the expected form are
// kept, so that a crafted HEAD ("ref: ../../../../etc/shadow"), gitdir or
// link never makes the agent read, and send, another file.
func readGit(fsys afero.Fs, root string) (*gitRepo, error) {
	dir := path.Join(root, ".git")
	if _, err := fsys.Stat(dir); errors.Is(err, fs.ErrNotExist) {
		return nil, nil
	}
	appFS, closeRoot, err := openRoot(fsys, root)
	if err != nil {
		return nil, err
	}
	defer closeRoot()
	info, err := fs.Stat(appFS, ".git")
	if errors.Is(err, fs.ErrNotExist) {
		return nil, nil // a link out of root
	}
	if err != nil {
		return nil, fmt.Errorf("%s: %w", dir, err)
	}
	gitDir := ".git"
	if !info.IsDir() {
		if gitDir, err = readGitdir(appFS, root); err != nil {
			return nil, err
		}
		dir = path.Join(root, gitDir)
	}
	gitFS := subFS{fsys: appFS, dir: gitDir}

	head, err := readSmall(gitFS, "HEAD", maxRefFile)
	if err != nil {
		return nil, fmt.Errorf("read %s: %w", path.Join(dir, "HEAD"), err)
	}
	refs := readPackedRefs(gitFS)
	repo := &gitRepo{}
	ref, symbolic := strings.CutPrefix(strings.TrimSpace(string(head)), "ref: ")
	switch {
	case symbolic:
		if !validRef(ref) {
			return nil, fmt.Errorf("%s: %w", path.Join(dir, "HEAD"), errInvalidRef)
		}
		repo.branch = strings.TrimPrefix(ref, "refs/heads/")
		repo.commit = resolveRef(gitFS, ref, refs)
	case shaRe.MatchString(ref):
		repo.commit = ref // detached HEAD
	}
	if repo.commit != "" {
		repo.tag = tagOf(gitFS, repo.commit, refs)
	}
	repo.remote = stripCredentials(originURL(gitFS))
	return repo, nil
}

// readGitdir reads the .git file of root and returns its gitdir relative to
// root; a gitdir out of root is refused.
func readGitdir(appFS fs.FS, root string) (string, error) {
	file := path.Join(root, ".git")
	b, err := readSmall(appFS, ".git", 4096)
	if err != nil {
		return "", fmt.Errorf("read %s: %w", file, err)
	}
	target, ok := strings.CutPrefix(strings.TrimSpace(string(b)), "gitdir: ")
	if !ok {
		return "", fmt.Errorf("%s: not a gitdir file", file)
	}
	if !path.IsAbs(target) {
		target = path.Join(root, target)
	}
	rel, ok := strings.CutPrefix(path.Clean(target), strings.TrimSuffix(path.Clean(root), "/")+"/")
	if !ok || !fs.ValidPath(rel) {
		return "", fmt.Errorf("%s: gitdir out of the app", file)
	}
	return rel, nil
}

func validRef(ref string) bool {
	return refRe.MatchString(ref) && !strings.Contains(ref, "..")
}

// openRoot opens dir as a file system confined to it: os.Root on the real
// file system, which refuses ".." and the links leading out of dir; a base
// path file system otherwise (tests), whose files have no links.
func openRoot(fsys afero.Fs, dir string) (fs.FS, func(), error) {
	if _, ok := fsys.(*afero.OsFs); ok {
		root, err := os.OpenRoot(dir)
		if err != nil {
			return nil, nil, err
		}
		return root.FS(), func() { _ = root.Close() }, nil
	}
	if _, err := fsys.Stat(dir); err != nil {
		return nil, nil, err
	}
	return afero.NewIOFS(afero.NewBasePathFs(fsys, dir)), func() {}, nil
}

// subFS is the directory dir of fsys. Unlike fs.Sub, it stats without
// opening, which would block on a FIFO.
type subFS struct {
	fsys fs.FS
	dir  string
}

func (s subFS) name(op, name string) (string, error) {
	if !fs.ValidPath(name) {
		return "", &fs.PathError{Op: op, Path: name, Err: fs.ErrInvalid}
	}
	return path.Join(s.dir, name), nil
}

func (s subFS) Open(name string) (fs.File, error) {
	full, err := s.name("open", name)
	if err != nil {
		return nil, err
	}
	return s.fsys.Open(full)
}

func (s subFS) Stat(name string) (fs.FileInfo, error) {
	full, err := s.name("stat", name)
	if err != nil {
		return nil, err
	}
	return fs.Stat(s.fsys, full)
}

func (s subFS) ReadDir(name string) ([]fs.DirEntry, error) {
	full, err := s.name("readdir", name)
	if err != nil {
		return nil, err
	}
	return fs.ReadDir(s.fsys, full)
}

var (
	errNotRegular = errors.New("not a regular file")
	errTooLarge   = errors.New("file too large")
)

// readSmall reads name of fsys, a regular file of at most limit bytes: a
// FIFO would block the read, /dev/zero never end it.
func readSmall(fsys fs.FS, name string, limit int) ([]byte, error) {
	info, err := fs.Stat(fsys, name)
	if err != nil {
		return nil, err
	}
	if !info.Mode().IsRegular() {
		return nil, errNotRegular
	}
	f, err := fsys.Open(name)
	if err != nil {
		return nil, err
	}
	defer func() { _ = f.Close() }()
	if info, err := f.Stat(); err != nil || !info.Mode().IsRegular() {
		return nil, errNotRegular
	}
	b, err := io.ReadAll(io.LimitReader(f, int64(limit)+1))
	if err != nil {
		return nil, err
	}
	if len(b) > limit {
		return nil, errTooLarge
	}
	return b, nil
}

// readPackedRefs maps the refs of packed-refs to their commit; a tag line
// is followed by "^<commit>" when annotated, which the tag then points to.
// Malformed lines are skipped.
func readPackedRefs(gitFS fs.FS) map[string]string {
	refs := map[string]string{}
	b, err := readSmall(gitFS, "packed-refs", maxPackedRefs)
	if err != nil {
		return refs
	}
	var last string
	scanner := bufio.NewScanner(bytes.NewReader(b))
	for scanner.Scan() {
		line := scanner.Text()
		switch {
		case strings.HasPrefix(line, "#"):
		case strings.HasPrefix(line, "^"):
			if hash := strings.TrimPrefix(line, "^"); last != "" && shaRe.MatchString(hash) {
				refs[last] = hash
			}
		default:
			last = ""
			if hash, name, ok := strings.Cut(line, " "); ok && shaRe.MatchString(hash) && validRef(name) {
				refs[name], last = hash, name
			}
		}
	}
	return refs
}

// resolveRef returns the commit of a valid ref, loose first then packed;
// empty when it is not a commit id.
func resolveRef(gitFS fs.FS, ref string, packed map[string]string) string {
	if b, err := readSmall(gitFS, ref, maxRefFile); err == nil {
		if commit := strings.TrimSpace(string(b)); shaRe.MatchString(commit) {
			return commit
		}
		return ""
	}
	return packed[ref]
}

// tagOf returns a tag pointing to commit, loose tags first, then packed
// ones; annotated tags are only found once packed.
func tagOf(gitFS fs.FS, commit string, packed map[string]string) string {
	if entries, err := fs.ReadDir(gitFS, "refs/tags"); err == nil {
		for _, e := range entries {
			ref := "refs/tags/" + e.Name()
			if validRef(ref) && resolveRef(gitFS, ref, nil) == commit {
				return e.Name()
			}
		}
	}
	var found string
	for name, hash := range packed {
		if tag, ok := strings.CutPrefix(name, "refs/tags/"); ok && hash == commit && (found == "" || tag < found) {
			found = tag
		}
	}
	return found
}

// originURL reads the URL of the origin remote in .git/config.
func originURL(gitFS fs.FS) string {
	b, err := readSmall(gitFS, "config", maxGitConfig)
	if err != nil {
		return ""
	}
	inOrigin := false
	scanner := bufio.NewScanner(bytes.NewReader(b))
	for scanner.Scan() {
		line := strings.TrimSpace(scanner.Text())
		if strings.HasPrefix(line, "[") {
			inOrigin = line == `[remote "origin"]`
			continue
		}
		if key, value, ok := strings.Cut(line, "="); ok && inOrigin && strings.TrimSpace(key) == "url" {
			return strings.TrimSpace(value)
		}
	}
	return ""
}

// credentialsRe matches the scheme and the credentials of an URL, up to its
// last "@": a password may hold "/", "?" or "@".
var credentialsRe = regexp.MustCompile(`^([A-Za-z][A-Za-z0-9+.-]*://).*@`)

// stripCredentials removes the user and password of an URL: a deploy token
// is often written in the remote. The URL is not parsed, so that one that
// does not parse (https://deploy:p%ss@…) or parses wrong
// (https://user:1234/abc@…) loses its credentials too. An scp-like
// git@host:path has no password and is kept.
func stripCredentials(raw string) string {
	return credentialsRe.ReplaceAllString(raw, "$1")
}

// repoName is the last element of a repository URL, without ".git":
// git@gitlab.example.com:client/api.git → api.
func repoName(remote string) string {
	remote = strings.TrimSuffix(strings.TrimRight(remote, "/"), ".git")
	if i := strings.LastIndexAny(remote, "/:"); i >= 0 {
		return remote[i+1:]
	}
	return remote
}
